using EqlTracker.Core;
using System.IO.Compression;
using System.Globalization;
using System.Text.Json;

internal static class HealingTests
{
    private static readonly DateTime Start = new(2026, 10, 15, 10, 0, 0, DateTimeKind.Local);
    private static ParsedLine Parse(string text, int seconds = 0, string? id = null) => new LogParser("ExampleHero").Parse($"[{Start.AddSeconds(seconds).ToString("ddd MMM dd HH:mm:ss yyyy", CultureInfo.InvariantCulture)}] {text}", id ?? Guid.NewGuid().ToString("N"))!;
    private static void Check(bool value) { if (!value) throw new Exception("Healing assertion failed"); }
    private static void Eq<T>(T expected, T actual) { if (!EqualityComparer<T>.Default.Equals(expected, actual)) throw new Exception($"Expected {expected}, got {actual}"); }
    private static CombatEngine Engine() => new(new() { Character = "ExampleHero", Zone = "Crushbone", PetIdentities = [new() { Name = "Cloudling", From = Start.AddHours(-1) }] });
    private static void Hit(CombatEngine engine, int seconds = 0) => engine.Process(Parse("You slash an orc for 100 points of damage.", seconds));
    public static void Register(Action<string, Action> test)
    {
        test("Partially expired healing uses exact summaries without double-counting remaining events", () => Temp(path => { var e = Engine(); Hit(e); e.Process(Parse("You healed yourself for 40 hit points by Heal.")); Hit(e, 10); e.Process(Parse("You healed yourself for 60 hit points by Heal.", 10)); using var s = new TrackerStore(path); s.SaveEncounter(e.Current!); s.Retain(Start.AddSeconds(5)); var f = s.LoadEncounters().Single(); Check(!f.HealingDetailAvailable); Eq(1, f.Heals.Count); var view = HealingMetrics.Build([f], [], new()); Eq(100L, view.Effective); Eq(2, view.Count); Eq(0, view.Rows.Count); Check(view.TotalsAvailable); }));
        test("Lifetap badges normalize rank and casing without guessing unknown spells", () => { Check(HealingIdentity.IsLifetap("spirit tap IV")); Check(HealingIdentity.IsLifetap("Vampiric Embrace 3")); Check(!HealingIdentity.IsLifetap("Unknown new spell")); });
        test("Healing export freezes attribution while pet corrections continue", () => { var e = Engine(); Hit(e); e.Process(Parse("Cloudling healed himself for 40 hit points by Spirit Tap.")); var view = DpsViews.Build([], e.Current, Start, new()); var doc = EncounterExporter.Snapshot(view, new(), HealingMetrics.Build([e.Current!], [], new())); e.Current!.Heals[0].HealerOwner = "Unknown"; Eq("Pet", doc.Healing!.Events[0].HealerOwner); Eq("Pet", doc.Encounters[0].Heals[0].HealerOwner); });
        test("A short fight exposes initial and final healing cadence boundaries", () => { var e = Engine(); Hit(e); var initial = HealingMetrics.Build([e.Current!], [], new()); e.Process(Parse("You healed yourself for 40 hit points by Heal.")); var first = HealingMetrics.Build([e.Current!], [], new()); Eq(40d, first.Hps); e.Process(Parse("An orc has been slain by ExampleHero!")); var killed = HealingMetrics.Build([e.Current!], [], new()); Check(first.Lifecycle != killed.Lifecycle); e.Finish(); var final = HealingMetrics.Build(e.Encounters, [], new()); Check(killed.Lifecycle != final.Lifecycle); Eq(first.Effective, final.Effective); Eq(0, initial.Count); });
        test("Healing parses actual restored HP separately from parenthesized raw amount", () => { var h = Parse("You healed ExampleHero for 122 (273) hit points by Spirit Tap.").Healing!; Eq(122L, h.Effective); Eq(273L, h.Raw!.Value); Eq(151L, h.Overheal!.Value); Check(h.Lifetap); Eq("ExampleHero", h.Healer); });
        test("Healing parses critical HoT and reflexive recipients", () => { var h = Parse("Friarr healed himself over time for 244 hit points by Blossoming Heal. (Critical)").Healing!; Check(h.OverTime && h.Critical); Eq("Friarr", h.Recipient); Eq("Blossoming Heal", h.Ability); });
        test("Zero-effective healing remains an event without inflating HP", () => { var h = Parse("You healed ExampleHero for 0 (269) hit points by Spirit Tap.").Healing!; Eq(0L, h.Effective); Eq(269L, h.Overheal!.Value); });
        test("Absent raw healing stays unknown", () => { var h = Parse("You healed yourself for 142 hit points by Spirit Tap.").Healing!; Eq("ExampleHero", h.Recipient); Check(h.Raw == null && h.Overheal == null); });
        test("Healing supports comma amounts and guards numeric overflow", () => { Eq(1234L, Parse("You healed Cloudling for 1,234 (2,345) hit points by Renew Elements.").Healing!.Effective); Check(Parse("You healed Cloudling for 9999999999999999999999999 hit points by Heal.").ParseWarning != null); });
        test("Lifetap damage and healing contribute only to their respective totals", () => { var e = Engine(); e.Process(Parse("You hit an orc for 273 points of magic damage by Spirit Tap I.")); e.Process(Parse("You healed ExampleHero for 122 (273) hit points by Spirit Tap.")); Eq(273L, e.Current!.Damage); Eq(122L, HealingMetrics.Build([e.Current], [], new()).Effective); Eq(1d, e.Current.Duration); });
        test("Heals alone never start fights", () => { var e = Engine(); e.Process(Parse("You healed ExampleHero for 100 hit points by Minor Healing.")); Check(e.Current == null); Eq(1, e.Healing.Events.Count); });
        test("Healing cannot extend, resume or prevent idle finalization", () => { var e = Engine(); Hit(e); Hit(e, 3); e.Process(Parse("You healed ExampleHero for 100 hit points by Heal.", 16)); e.Tick(Start.AddSeconds(34)); Check(e.Current == null); Eq(3d, e.Encounters.Single().Duration); Eq("", e.Healing.Events.Single().EncounterId); });
        test("Healing inside a resumed fear gap becomes encounter healing", () => { var e = Engine(); Hit(e); e.Tick(Start.AddSeconds(13)); e.Process(Parse("You healed yourself for 70 hit points by Spirit Tap.", 15)); Check(e.Current!.IdleResumable); Eq(0, e.Current.Heals.Count); Hit(e, 18); Eq(1, e.Current.Heals.Count); Eq(18d, e.Current.Duration); Eq(70d / 18, HealingMetrics.Build([e.Current], [], new()).Hps); });
        test("Recovery healing after a kill stays outside the fight", () => { var e = Engine(); Hit(e); e.Process(Parse("An orc has been slain by ExampleHero!", 1)); e.Process(Parse("You healed yourself for 70 hit points by Spirit Tap.", 2)); e.Tick(Start.AddSeconds(32)); Eq(0, e.Encounters.Single().Heals.Count); Eq(70L, HealingMetrics.Build(e.Encounters, e.Healing.Events, new()).OutsideCombat); });
        test("Distinct identical heals in the same second survive while rereads deduplicate", () => { var e = Engine(); Hit(e); var first = Parse("You healed yourself for 70 hit points by Spirit Tap.", 0, "heal:1"); e.Process(first); e.Process(Parse("You healed yourself for 70 hit points by Spirit Tap.", 0, "heal:2")); e.Process(first); Eq(2, e.Current!.Heals.Count); Eq(140L, HealingMetrics.Build([e.Current], [], new()).Effective); });
        test("Done and received do not add self-healing twice", () => { var e = Engine(); Hit(e); e.Process(Parse("You healed yourself for 70 hit points by Spirit Tap.")); Eq(70L, HealingMetrics.Build([e.Current!], [], new()).Effective); Eq(70L, HealingMetrics.Build([e.Current!], [], new(Direction: "Received")).Effective); });
        test("Incoming healing retains named healers outside the confirmed roster", () => { var e = Engine(); Hit(e); e.Process(Parse("Helpfulcleric healed ExampleHero for 120 hit points by Healing.")); Eq(0L, HealingMetrics.Build([e.Current!], [], new()).Effective); var h = HealingMetrics.Build([e.Current!], [], new(Direction: "Received")); Eq(120L, h.Effective); Eq("Helpfulcleric", h.Healers.Single().Name); });
        test("Pet healing attribution uses the identity interval", () => { var e = Engine(); Hit(e); e.Process(Parse("Cloudling healed himself for 40 hit points by Spirit Tap.")); e.Process(Parse("You healed Cloudling for 60 hit points by Renew Elements.")); Eq(40L, HealingMetrics.Build([e.Current!], [], new(Owner: "Pet")).Effective); Eq(100L, HealingMetrics.Build([e.Current!], [], new(Direction: "Received", Owner: "Pet")).Effective); });
        test("Late pet identity correction updates healing and attribution evidence", () => { var e = new CombatEngine(new() { Character = "ExampleHero" }); Hit(e); e.Process(Parse("Newpet healed himself for 40 hit points by Spirit Tap.")); Eq(0L, HealingMetrics.Build([e.Current!], [], new()).Effective); e.ConfirmPet("Newpet", Start.AddSeconds(-1), null); Eq(40L, HealingMetrics.Build([e.Current!], [], new(Owner: "Pet")).Effective); Check(e.Current!.Heals.Single().AttributionEvidence.Contains("owned pet")); });
        test("Healing filters use the common denominator", () => { var e = Engine(); Hit(e); e.Process(Parse("You healed yourself for 70 hit points by Spirit Tap.")); e.Process(Parse("You healed Cloudling over time for 30 hit points by Renewal. (Critical)", 4)); Hit(e, 10); var h = HealingMetrics.Build([e.Current!], [], new(Kind: "HoT", CriticalOnly: true)); Eq(30L, h.Effective); Eq(3d, h.Hps); Eq(10d, h.Seconds); Eq(100d, h.Rows.Single().CriticalPercent); });
        test("Session HPS sums fight durations and separates outside healing", () => { var e = Engine(); Hit(e); e.Process(Parse("You healed yourself for 100 hit points by Heal.")); Hit(e, 10); e.Finish(); e.Process(Parse("You healed yourself for 50 hit points by Heal.", 20)); Hit(e, 40); e.Process(Parse("You healed yourself for 100 hit points by Heal.", 40)); Hit(e, 50); e.Finish(); var h = HealingMetrics.Build(e.Encounters, e.Healing.Events, new()); Eq(20d, h.Seconds); Eq(10d, h.Hps); Eq(50L, h.OutsideCombat); });
        test("Healing persistence, restart and ownership metadata reconcile", () => Temp(path => { var e = Engine(); Hit(e); e.Process(Parse("You healed yourself for 40 (100) hit points by Spirit Tap.")); using (var s = new TrackerStore(path)) { s.SaveEncounter(e.Current!); } using var restored = new TrackerStore(path); var f = restored.LoadEncounters().Single(); Eq(40L, f.Heals.Single().Effective); Eq(40L, HealingMetrics.Build([f], [], new()).Effective); Eq(60L, f.Heals.Single().Overheal!.Value); }));
        test("Healing retention preserves summary totals without invented spell rows", () => Temp(path => { var e = Engine(); Hit(e); e.Process(Parse("You healed yourself for 40 hit points by Heal.")); using var s = new TrackerStore(path); s.SaveEncounter(e.Current!); s.Retain(Start.AddDays(31)); var f = s.LoadEncounters().Single(); Check(!f.HealingDetailAvailable); var h = HealingMetrics.Build([f], [], new()); Eq(40L, h.Effective); Eq(0, h.Rows.Count); Check(!h.DetailComplete); Check(!HealingMetrics.Build([f], [], new(Ability: "Heal")).TotalsAvailable); }));
        test("Legacy encounter healing is unavailable rather than a verified zero", () => { var h = HealingMetrics.Build([new() { Start = Start, End = Start.AddSeconds(10) }], [], new()); Eq("Unavailable", h.Coverage); Check(!h.TotalsAvailable); });
        test("Healing merge and split preserve IDs without duplicated totals", () => { var e = Engine(); Hit(e); e.Process(Parse("You healed yourself for 40 hit points by Heal.")); Hit(e, 2); e.Finish(); Hit(e, 10); e.Process(Parse("You healed yourself for 60 hit points by Heal.", 10)); Hit(e, 12); e.Finish(); var merged = EncounterEdits.Merge(e.Encounters[0], e.Encounters[1]); Eq(100L, HealingMetrics.Build([merged], [], new()).Effective); var split = EncounterEdits.Split(merged, Start.AddSeconds(6)); Eq(100L, HealingMetrics.Build(split, [], new()).Effective); Eq(2, split.SelectMany(f => f.Heals).Select(h => h.Id).Distinct().Count()); });
        test("Replacing and undoing encounters restores healing associations", () => Temp(path => { var e = Engine(); Hit(e); e.Process(Parse("You healed yourself for 40 hit points by Heal.")); Hit(e, 2); e.Finish(); Hit(e, 10); e.Process(Parse("You healed yourself for 60 hit points by Heal.", 10)); e.Finish(); using var s = new TrackerStore(path); foreach (var f in e.Encounters) s.SaveEncounter(f); var merged = EncounterEdits.Merge(e.Encounters[0], e.Encounters[1]); s.ReplaceEncounters(e.Encounters.Select(f => f.Id), [merged], null); Eq(100L, s.LoadEncounters().Single().Heals.Sum(h => h.Effective)); s.ReplaceEncounters([merged.Id], e.Encounters, null); Eq(100L, s.LoadEncounters().SelectMany(f => f.Heals).Sum(h => h.Effective)); }));
        test("Healing backfill checkpoints are atomic and rereads retain event identity", () => Temp(path => { var e = Engine(); Hit(e); var h = Parse("You healed yourself for 40 hit points by Heal.", id: "file-generation:50").Healing!; e.Healing.AssignHistorical(h, e.Current!.Zone, e.Current); HealingLedger.Summarize(e.Current); using (var s = new TrackerStore(path)) s.CommitHealingBackfill(new() { Offset = 500, Generation = "file-generation" }, e.Healing.PendingWrites, [e.Current]); using var restored = new TrackerStore(path); Eq(500L, restored.Get<FileCheckpoint>("healingBackfill")!.Offset); var ledger = new HealingLedger(new() { Character = "ExampleHero" }); ledger.Restore(restored.LoadHealing()); ledger.AssignHistorical(h.Copy(), e.Current.Zone, null); Eq(1, ledger.Events.Count); }));
        test("Version 3 healing export matches filtered effective totals and freezes active fights", () => Temp(path => { var e = Engine(); Hit(e); e.Process(Parse("You healed yourself for 40 (100) hit points by Spirit Tap.")); var damage = DpsViews.Build([], e.Current, Start, new() { Actor = "Combined" }); var document = EncounterExporter.Snapshot(damage, new() { Character = "ExampleHero" }); Eq(3, document.Version); Eq(40L, document.Healing!.Effective); Check(!e.Current!.Finished); var zipPath = path + ".zip"; try { EncounterExporter.Write(zipPath, document); using var zip = ZipFile.OpenRead(zipPath); Check(zip.GetEntry("healing_events.csv") != null && zip.GetEntry("healing_spells.csv") != null && zip.GetEntry("healing_recipients.csv") != null); using var reader = new StreamReader(zip.GetEntry("encounters.json")!.Open()); var copy = JsonSerializer.Deserialize<EncounterExportDocument>(reader.ReadToEnd(), Json.Options)!; Eq(40L, copy.Healing!.Effective); Eq(100L, copy.Damage); } finally { File.Delete(zipPath); } }));
        test("Healing rejects quoted chat and invalid raw amounts", () => { Check(Parse("Helpfulcleric tells you, 'You healed ExampleHero for 40 hit points by Heal.'").Healing == null); var h = Parse("You healed yourself for 100 (50) hit points by Heal.").Healing!; Check(h.Overheal == null); });
    }
    private static void Temp(Action<string> run)
    {
        var path = Path.Combine(Path.GetTempPath(), "eql-healing-" + Guid.NewGuid().ToString("N") + ".db");
        try { run(path); } finally { Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools(); foreach (var suffix in new[] { "", "-wal", "-shm" }) File.Delete(path + suffix); }
    }
}
